class DeterministicRNG:
    """Seeded PRNG for all simulation randomness. Ensures reproducibility."""

    def __init__(self, seed: int):
        self._rng = random.Random(seed)
        self._seed = seed

    def random(self) -> float:
        return self._rng.random()

    def uniform(self, a: float, b: float) -> float:
        return self._rng.uniform(a, b)

    def choice(self, seq: List[Any]) -> Any:
        return self._rng.choice(seq)

    def randint(self, a: int, b: int) -> int:
        return self._rng.randint(a, b)

    def shuffle(self, seq: List[Any]) -> None:
        self._rng.shuffle(seq)

    def get_seed(self) -> int:
        return self._seed


class VirtualClock:
    """Monotonic virtual time. Advances in discrete steps."""

    def __init__(self, start_time: int = 0):
        self._current_time = start_time

    def now(self) -> int:
        return self._current_time

    def advance(self, delta: int) -> None:
        if delta < 0:
            raise ValueError("Cannot advance clock backwards")
        self._current_time += delta

    def set(self, time: int) -> None:
        if time < self._current_time:
            raise ValueError("Cannot set clock backwards")
        self._current_time = time


class TraceRecorder:
    """Immutable log of all simulation events. Ground truth for assertions."""

    def __init__(self):
        self._events: List[Dict[str, Any]] = []

    def record(self, event: Event, context: Dict[str, Any]) -> None:
        entry = {
            "timestamp": event.timestamp,
            "sequence": event.sequence,
            "node_id": event.node_id,
            "event_type": event.type.name,
            "payload": event.payload,
            "context": context,
        }
        self._events.append(entry)

    def get_trace(self) -> List[Dict[str, Any]]:
        return list(self._events)

    def serialize(self, filepath: str) -> None:
        with open(filepath, "w") as f:
            json.dump(self._events, f, indent=2)

    def __len__(self) -> int:
        return len(self._events)


