# --- Simulation Harness ------------------------------------------------------

class SimulationHarness:
    """
    Deterministic discrete-event simulation harness.

    Usage:
        harness = SimulationHarness(seed=42)
        harness.register_node("node_a", node_a_instance)
        harness.register_node("node_b", node_b_instance)
        harness.schedule_fault(FaultSpec(FaultType.NODE_CRASH, node_id="node_a"), timestamp=100)
        harness.run(max_steps=1000)
        trace = harness.get_trace()
    """

    def __init__(self, seed: int = 0):
        self._rng = DeterministicRNG(seed)
        self._clock = VirtualClock()
        self._trace = TraceRecorder()
        self._fault_injector = FaultInjector(self._rng)
        self._event_queue: List[Event] = []
        self._sequence_counter = 0
        self._nodes: Dict[str, Any] = {}
        self._fault_schedule: List[Tuple[int, FaultSpec]] = []
        self._invariants: List[Callable[[Dict[str, Any]], Optional[str]]] = []
        self._current_step = 0
        self._max_steps = 10000

    def register_node(self, node_id: str, node_instance: Any) -> None:
        """Register a node with the simulation."""
        self._nodes[node_id] = node_instance

    def schedule_fault(self, spec: FaultSpec, timestamp: int) -> None:
        """Schedule a fault to be injected at the given virtual time."""
        self._fault_schedule.append((timestamp, spec))
        self._fault_schedule.sort(key=lambda x: x[0])

    def add_invariant(self, checker: Callable[[Dict[str, Any]], Optional[str]]) -> None:
        """Add an invariant checker. Returns error message if violated, None otherwise."""
        self._invariants.append(checker)

    def schedule_event(self, timestamp: int, node_id: str, event_type: EventType, payload: Dict[str, Any]) -> None:
        """Schedule a new event at the given virtual time."""
        event = Event(
            timestamp=timestamp,
            sequence=self._sequence_counter,
            node_id=node_id,
            type=event_type,
            payload=payload,
        )
        self._sequence_counter += 1
        heapq.heappush(self._event_queue, event)

    def run(self, max_steps: Optional[int] = None) -> None:
        """Run the simulation until the event queue is empty or max_steps reached."""
        if max_steps is not None:
            self._max_steps = max_steps

        while self._event_queue and self._current_step < self._max_steps:
            # Process any pending fault injections at current time
            self._process_pending_faults()

            # Pop next event
            event = heapq.heappop(self._event_queue)
            self._clock.set(event.timestamp)

            # Check if node is crashed or paused
            if self._fault_injector.is_node_crashed(event.node_id):
                self._trace.record(event, {"status": "dropped_crashed_node"})
                continue

            if self._fault_injector.is_node_paused(event.node_id):
                # Re-schedule event after pause duration
                pause_remaining = self._fault_injector._paused_nodes[event.node_id]
                self.schedule_event(
                    event.timestamp + pause_remaining,
                    event.node_id,
                    event.type,
                    event.payload,
                )
                self._trace.record(event, {"status": "deferred_paused_node"})
                continue

            # Apply message loss
            if event.type == EventType.MESSAGE_DELIVERY:
                if self._fault_injector.should_drop_message(event.node_id):
                    self._trace.record(event, {"status": "dropped_message_loss"})
                    continue

            # Apply latency override
            latency = self._fault_injector.get_latency(event.node_id)
            if latency > 0 and event.type == EventType.MESSAGE_DELIVERY:
                # Re-schedule with latency
                self.schedule_event(
                    event.timestamp + latency,
                    event.node_id,
                    event.type,
                    event.payload,
                )
                self._trace.record(event, {"status": "deferred_latency"})
                continue

            # Dispatch event to node
            self._dispatch_event(event)

            # Record event in trace
            self._trace.record(event, {"status": "processed"})

            # Check invariants after each event
            self._check_invariants()

            # Advance clock and pause states
            self._fault_injector.advance_pauses(1)
            self._current_step += 1

        # Process any remaining fault injections
        self._process_pending_faults()

    def _process_pending_faults(self) -> None:
        """Inject any faults scheduled at or before current time."""
        while self._fault_schedule and self._fault_schedule[0][0] <= self._clock.now():
            timestamp, spec = self._fault_schedule.pop(0)
            self._fault_injector.apply(spec, self._clock)
            self._trace.record(
                Event(
                    timestamp=timestamp,
                    sequence=self._sequence_counter,
                    node_id=spec.node_id or "system",
                    type=EventType.FAULT_TRIGGER,
                    payload={"fault_type": spec.fault_type.name, "params": spec.params},
                ),
                {"status": "fault_injected"},
            )
            self._sequence_counter += 1

    def _dispatch_event(self, event: Event) -> None:
        """Dispatch an event to the appropriate node handler."""
        node = self._nodes.get(event.node_id)
        if node is None:
            raise ValueError(f"Unknown node: {event.node_id}")

        handler = getattr(node, f"handle_{event.type.name.lower()}", None)
        if handler is None:
            raise ValueError(f"Node {event.node_id} has no handler for {event.type.name}")

        handler(event.payload)

    def _check_invariants(self) -> None:
        """Run all invariant checkers against current state."""
        state_snapshot = self._get_state_snapshot()
        for checker in self._invariants:
            error = checker(state_snapshot)
            if error is not None:
                raise AssertionError(f"Invariant violation: {error}")

    def _get_state_snapshot(self) -> Dict[str, Any]:
        """Collect current state from all nodes."""
        snapshot = {}
        for node_id, node in self._nodes.items():
            if hasattr(node, "get_state"):
                snapshot[node_id] = node.get_state()
        return snapshot

    def get_trace(self) -> List[Dict[str, Any]]:
        return self._trace.get_trace()

    def serialize_trace(self, filepath: str) -> None:
        self._trace.serialize(filepath)

    def get_clock(self) -> VirtualClock:
        return self._clock

    def get_rng(self) -> DeterministicRNG:
        return self._rng

    def get_fault_injector(self) -> FaultInjector:
        return self._fault_injector


# --- Standard Invariants -----------------------------------------------------

def invariant_no_message_loss(state: Dict[str, Any]) -> Optional[str]:
    """Example invariant: no node should have lost messages."""
    for node_id, node_state in state.items():
        if "lost_messages" in node_state and node_state["lost_messages"] > 0:
            return f"Node {node_id} lost {node_state['lost_messages']} messages"
    return None


def invariant_consensus_safety(state: Dict[str, Any]) -> Optional[str]:
    """Example invariant: consensus safety (no conflicting decisions)."""
    decisions = {}
    for node_id, node_state in state.items():
        if "decision" in node_state:
            decision = node_state["decision"]
            if decision in decisions and decisions[decision] != node_id:
                return f"Conflicting decisions: {decisions[decision]} and {node_id} both decided {decision}"
            decisions[decision] = node_id
    return None


# --- Fixture Loading ---------------------------------------------------------

def load_fixture(filepath: str) -> Dict[str, Any]:
    """Load a fault-injection fixture from YAML/JSON."""
    import yaml

    with open(filepath, "r") as f:
        if filepath.endswith(".yaml") or filepath.endswith(".yml"):
            return yaml.safe_load(f)
        else:
            return json.load(f)


def build_harness_from_fixture(fixture: Dict[str, Any]) -> SimulationHarness:
    """Build a simulation harness from a fixture specification."""
    seed = fixture.get("seed", 0)
    harness = SimulationHarness(seed=seed)

    # Register nodes (assuming node factory is provided)
    node_factory = fixture.get("node_factory")
    if node_factory is None:
        raise ValueError("Fixture must provide node_factory")

    for node_spec in fixture.get("nodes", []):
        node_id = node_spec["id"]
        node_instance = node_factory(node_id, node_spec.get("config", {}))
        harness.register_node(node_id, node_instance)

    # Schedule faults
    for fault_spec in fixture.get("fault_schedule", []):
        spec = FaultSpec(
            fault_type=FaultType[fault_spec["type"]],
            node_id=fault_spec.get("node_id"),
            target_node_id=fault_spec.get("target_node_id"),
            params=fault_spec.get("params", {}),
        )
        harness.schedule_fault(spec, fault_spec["timestamp"])

    # Add invariants
    for invariant_name in fixture.get("invariants", []):
        invariant = globals().get(f"invariant_{invariant_name}")
        if invariant is not None:
            harness.add_invariant(invariant)

    return harness


